CREATE TABLE "monitoring_events" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "monitoring_events_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"event_id" varchar(36) NOT NULL,
	"event_type" varchar(80) NOT NULL,
	"category" varchar(24) NOT NULL,
	"severity" varchar(16) NOT NULL,
	"occurred_at" timestamp with time zone NOT NULL,
	"source_service" varchar(40) NOT NULL,
	"instance_id" varchar(120) NOT NULL,
	"correlation_id" varchar(36),
	"related_resource_id" varchar(80),
	"metadata" jsonb NOT NULL,
	"ingested_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "monitoring_events_event_id_unique" UNIQUE("event_id"),
	CONSTRAINT "monitoring_events_category_check" CHECK ("monitoring_events"."category" IN ('request', 'application', 'security', 'business', 'system')),
	CONSTRAINT "monitoring_events_severity_check" CHECK ("monitoring_events"."severity" IN ('debug', 'info', 'warning', 'error', 'critical'))
);
